            raise OtherError("issuer != iss")
        if self.client_id not in id_token["aud"]:
            raise OtherError("not intended for me")
        if len(id_token["aud"]) > 1:
            if "azp" not in id_token or id_token["azp"] != self.client_id:
                raise OtherError("not intended for me")
