            raise OtherError("acr mismatch")
        if max_age and _now > int(id_token["auth_time"] + max_age):
            raise AuthnToOld("To old authentication")
        if auth_time:
            if not claims_match(id_token["auth_time"], {"auth_time": auth_time}):
                raise AuthnToOld("To old authentication")
