        return IRnode.from_list(len(arg.args), typ=typ)
    if arg.value == "~empty":
        return IRnode.from_list(0, typ=typ)
    return IRnode.from_list(LOAD(arg), typ=typ)
def getpos(node):
    return (
        node.lineno,
        node.col_offset,
        getattr(node, "end_lineno", None),
        getattr(node, "end_col_offset", None),
    )
