        parent = add_ofst(parent, parent.location.word_scale * DYNAMIC_ARRAY_OVERHEAD)
    ofst_ir = add_ofst(parent, ofst)
    if member_abi_t.is_dynamic():
        ofst_ir = add_ofst(parent, unwrap_location(ofst_ir))
