        arg = _int_to_int(arg, out_typ)
    elif is_integer_type(arg.typ):
        arg = _int_to_int(arg, out_typ)
    elif arg.typ == AddressT():
        if out_typ.is_signed:
            _FAIL(arg.typ, out_typ, expr)
